contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint out) public payable {
        require(amount > 1 ether);
        require(address(this).balance >= amount);
        c.Deposit{value: amount}();
        uint recordedAfterDeposit = c.balances(address(this));
        uint cBalBefore = address(c).balance;

        uint outAmount = out;
        bool reverted;
        if (outAmount > recordedAfterDeposit) {
            try c.CashOut(outAmount) { reverted = false; } catch { reverted = true; }
        } else {
            c.CashOut(outAmount);
            reverted = false;
        }

        uint cBalAfter = address(c).balance;
        if (reverted) {
            assert(cBalAfter == cBalBefore);
        } else {
            assert(recordedAfterDeposit >= outAmount && cBalAfter == cBalBefore - outAmount);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint out) public payable {
        require(amount > c.MinDeposit());
        require(address(this).balance >= amount);

        c.Deposit{value: amount}();

        uint recordedBefore = c.balances(address(this));
        require(out <= recordedBefore);
        uint cBalBefore = address(c).balance;

        c.CashOut(out);

        assert(
            c.balances(address(this)) == recordedBefore - out &&
            address(c).balance == cBalBefore - out
        );
    }

    receive() external payable {}
}

